% export_clips_revisit_rate_tables.m
% Re-export the CLIPS revisit-rate audit tables from the raw CLIPS summaries
% and the metric table generated by build_dcta_paired_metric_results.m.
%
% Rate definition: system_revisits / total_team_steps for each trial.
% The condition table carries arithmetic means of individual trial rates from
% the metric pipeline's common six-algorithm eligible blocks.

analysisDir = string(fileparts(mfilename("fullpath")));
projectRoot = string(fileparts(fileparts(analysisDir)));
tablesDir = fullfile(analysisDir, "tables");
combinedDir = fullfile(projectRoot, "results", "clue_search_core_500", "combined");
systemPath = fullfile(combinedDir, "clue_search_core_500_combined_system_performance.csv");
trialPath = fullfile(combinedDir, "clue_search_core_500_combined_trial_summary.csv");
metricPath = fullfile(tablesDir, "dcta_metric_results.csv");
trialOutPath = fullfile(tablesDir, "clips_system_cell_revisit_rate_trial_values.csv");
conditionOutPath = fullfile(tablesDir, "clips_system_cell_revisit_rate_condition_summary.csv");
clipsScenario = "Clue-Informed Probabilistic Search (CLIPS)";
algorithmOrder = ["CBAA","ACBBA","PI","HIPC","DMCHBA","DGA"];

systemOpts = detectImportOptions(systemPath, "FileType", "text", "Delimiter", ",", "TextType", "string");
trialOpts = detectImportOptions(trialPath, "FileType", "text", "Delimiter", ",", "TextType", "string");
systemOpts = setvartype(systemOpts, "comm_level", "string");
trialOpts = setvartype(trialOpts, "comm_level", "string");
systemT = readtable(systemPath, systemOpts);
trialT = readtable(trialPath, trialOpts);
metricT = readtable(metricPath, "TextType", "string");

for Tname = ["systemT","trialT"]
    T = eval(Tname); %#ok<EVLDIR>
    T.trial_id = string(T.trial_id);
    T.algorithm = upper(string(T.algorithm));
    T.comm_model = lower(string(T.comm_model));
    T.comm_model(T.comm_model == "gilbert_elliot") = "gilbert_elliott";
    T.comm_level = string(T.comm_level);
    % Preserve the raw level for output, but use an explicit token when the
    % ideal condition has a blank level. Missing-string equality does not
    % produce a usable logical match in MATLAB.
    T.comm_level_key = T.comm_level;
    missingLevel = ismissing(T.comm_level_key) | ...
        strlength(strtrim(T.comm_level_key)) == 0;
    T.comm_level_key(missingLevel) = "<ideal>";
    T.key = T.trial_id + "|" + T.algorithm + "|" + T.comm_model + "|" + T.comm_level_key;
    eval(Tname + " = T;"); %#ok<EVLDIR>
end

if numel(unique(systemT.key)) ~= height(systemT) || numel(unique(trialT.key)) ~= height(trialT)
    error("CLIPS raw inputs contain duplicate system or trial-summary keys.");
end
[matchedTrial, trialLoc] = ismember(systemT.key, trialT.key);
trialStatus = strings(height(systemT), 1);
firstClueRobot = strings(height(systemT), 1);
trialStatus(matchedTrial) = lower(string(trialT.trial_status(trialLoc(matchedTrial))));
firstClueRobot(matchedTrial) = string(trialT.first_clue_robot(trialLoc(matchedTrial)));

systemStatus = lower(string(systemT.trial_status));
systemRevisits = double(systemT.system_revisits);
totalTeamSteps = double(systemT.total_team_steps);
rate = NaN(height(systemT), 1);
validDenominator = isfinite(totalTeamSteps) & totalTeamSteps > 0;
rate(validDenominator) = systemRevisits(validDenominator) ./ totalTeamSteps(validDenominator);
baseEligible = systemStatus == "completed" & trialStatus == "completed" & ...
    ~ismissing(firstClueRobot) & strlength(strtrim(firstClueRobot)) > 0;
rateEligible = baseEligible & isfinite(rate);

commonBlockEligible = false(height(systemT), 1);
blocks = unique(systemT(:, ["trial_id","comm_model","comm_level_key"]), "rows", "stable");
for b = 1:height(blocks)
    mask = systemT.trial_id == blocks.trial_id(b) & ...
        systemT.comm_model == blocks.comm_model(b) & ...
        systemT.comm_level_key == blocks.comm_level_key(b);
    algorithmsPresent = unique(systemT.algorithm(mask), "stable");
    exactAlgorithmSet = numel(algorithmsPresent) == numel(algorithmOrder) && ...
        all(ismember(algorithmOrder, algorithmsPresent));
    commonBlockEligible(mask) = sum(mask) == numel(algorithmOrder) && ...
        exactAlgorithmSet && all(rateEligible(mask));
end

trialOutput = table( ...
    repmat(clipsScenario, height(systemT), 1), systemT.trial_id, systemT.algorithm, ...
    systemT.comm_model, systemT.comm_level, systemStatus, trialStatus, firstClueRobot, ...
    totalTeamSteps, systemRevisits, rate, baseEligible, rateEligible, commonBlockEligible, ...
    'VariableNames', {'scenario','trial_id','algorithm','comm_model','comm_level_raw', ...
    'system_trial_status','trial_summary_status','first_clue_robot','total_team_steps', ...
    'system_revisits','revisits_per_team_step','base_eligible','rate_metric_eligible', ...
    'common_six_algorithm_block_eligible'});
trialOutput = sortrows(trialOutput, {'comm_model','comm_level_raw','trial_id','algorithm'});

keep = metricT.scenario == clipsScenario & ...
    metricT.metric == "system_cell_revisit_rate" & ...
    metricT.result_type == "condition_metric";
conditionOutput = metricT(keep, ["comm_model","comm_level_raw","comm_level_pct","algorithm", ...
    "total_trial_count","eligible_paired_trials","excluded_trials", ...
    "mean_value","median_value","standard_deviation","ci95_low","ci95_high"]);
conditionOutput.Properties.VariableNames = {'comm_model','comm_level_raw','comm_level_pct','algorithm', ...
    'attempted_trial_blocks','eligible_common_six_algorithm_blocks','excluded_trial_blocks', ...
    'mean_revisits_per_team_step','median_revisits_per_team_step', ...
    'standard_deviation_revisits_per_team_step','ci95_low','ci95_high'};
conditionOutput = sortrows(conditionOutput, {'comm_model','comm_level_pct','algorithm'});

if height(conditionOutput) ~= 150
    error("Expected 150 CLIPS condition-by-algorithm rate means; found %d.", height(conditionOutput));
end
formulaRows = isfinite(trialOutput.system_revisits) & isfinite(trialOutput.total_team_steps) & ...
    trialOutput.total_team_steps > 0 & isfinite(trialOutput.revisits_per_team_step);
expectedRate = trialOutput.system_revisits(formulaRows) ./ trialOutput.total_team_steps(formulaRows);
if any(abs(trialOutput.revisits_per_team_step(formulaRows) - expectedRate) > 1e-12)
    error("Rate verification failed: revisit rate differs from system_revisits / total_team_steps.");
end
if any(~isfinite(trialOutput.revisits_per_team_step(trialOutput.common_six_algorithm_block_eligible)))
    error("An eligible common block contains a nonfinite revisit rate.");
end

writetable(trialOutput, trialOutPath);
writetable(conditionOutput, conditionOutPath);
fprintf("PASS: wrote %d raw CLIPS trial rows and %d condition-by-algorithm rate means.\n", ...
    height(trialOutput), height(conditionOutput));
fprintf("PASS: common six-algorithm blocks retained: %d.\n", ...
    sum(trialOutput.common_six_algorithm_block_eligible) / numel(algorithmOrder));
